"""Console match-3 game: swap adjacent candies, clear matches, chain cascades."""
from game import Board

ROWS, COLS, TYPES = 8, 8, 5
MOVES, TARGET = 20, 2000


def parse_int(text, lo, hi):
    try:
        value = int(text)
    except ValueError:
        return None
    return value if lo <= value <= hi else None


def read_move(board):
    while True:
        try:
            raw = input("Move 'r1 c1 r2 c2' | h=hint | q=quit: ").strip().lower()
        except EOFError:
            return None
        if raw in ("q", "quit", "exit"):
            return None
        if raw in ("h", "hint"):
            spot = board.hint()
            if spot:
                print(f"Hint: swap {spot[0]} with {spot[1]}.")
            else:
                print("No moves available -- shuffling the board.")
                board.shuffle()
            continue
        parts = raw.replace(",", " ").split()
        if len(parts) != 4:
            print("Enter four numbers, e.g. 3 2 3 3.")
            continue
        r1 = parse_int(parts[0], 0, ROWS - 1)
        c1 = parse_int(parts[1], 0, COLS - 1)
        r2 = parse_int(parts[2], 0, ROWS - 1)
        c2 = parse_int(parts[3], 0, COLS - 1)
        if None in (r1, c1, r2, c2):
            print("Coordinates out of range.")
            continue
        return (r1, c1), (r2, c2)


def main():
    board = Board(ROWS, COLS, TYPES)
    score, moves = 0, MOVES
    print("=== Candy Match ===")
    print(f"Line up 3+ candies to score. Reach {TARGET} points in {MOVES} moves.")
    while moves > 0 and score < TARGET:
        print()
        print(board.render())
        print(f"Score: {score} | Moves left: {moves} | Target: {TARGET}")
        move = read_move(board)
        if move is None:
            print(f"Goodbye! Final score: {score}.")
            return
        a, b = move
        if not board.adjacent(a, b):
            print("The two candies must be adjacent.")
            continue
        if not board.try_swap(a, b):
            print("That swap makes no match -- reverted.")
            continue
        points, chain = board.resolve()
        score += points
        moves -= 1
        message = f"+{points} points"
        if chain > 1:
            message += f" -- chain reaction x{chain}!"
        print(message)
        if not board.has_move():
            print("No possible moves -- shuffling the board.")
            board.shuffle()
    print()
    print(board.render())
    print("YOU WIN!" if score >= TARGET else "Out of moves.")
    print(f"Final score: {score} / {TARGET}.")


if __name__ == "__main__":
    main()
